// tax period; an accountant reconciling a quarter needs the first date and
// nothing else on this object tells them what it was.
type InvoiceSummary struct {
	Id         *openapi_types.UUID   `json:"id,omitempty"`
	IssuedAt   *time.Time            `json:"issued_at,omitempty"`
	Kind       *InvoiceSummaryKind   `json:"kind,omitempty"`
	Number     *string               `json:"number,omitempty"`
	Status     *InvoiceSummaryStatus `json:"status,omitempty"`
	SupplyDate *openapi_types.Date   `json:"supply_date,omitempty"`

	// Tax Integer minor units. `1250` + `AED` is 12.50 AED.
	Tax *Money `json:"tax,omitempty"`

	// Total Integer minor units. `1250` + `AED` is 12.50 AED.
	Total *Money `json:"total,omitempty"`
}

// InvoiceSummaryKind defines model for InvoiceSummary.Kind.
type InvoiceSummaryKind string

// InvoiceSummaryStatus defines model for InvoiceSummary.Status.
type InvoiceSummaryStatus string

